declare module 'labflow-slug' {
  export const SLUG_MAX: number;
  export function slugify(text: string): string;
  export function truncate(text: string, max: number): string;
  export function isSlug(value: string): boolean;
}

import { slugify, truncate, isSlug, SLUG_MAX } from 'labflow-slug';
const s: string = slugify('Phong Lab');
const t: string = truncate('hello world', 5);
const ok: boolean = isSlug('be-201');
const max: number = SLUG_MAX;
export { s, t, ok, max };

